// This file is generated by AI.

// 欢迎页: 打开项目、最近项目、主题切换、设置入口。

import { open } from '@tauri-apps/plugin-dialog';
import { Button, Spinner } from '@fluentui/react-components';
import { FolderOpenRegular, SettingsRegular, WeatherMoonRegular, WeatherSunnyRegular } from '@fluentui/react-icons';
import { useState } from 'react';

import { openProject } from '../project';
import { useAppStore } from '../state/store';

export function WelcomePage() {
  const settings = useAppStore((s) => s.settings);
  const theme = useAppStore((s) => s.theme);
  const updateSettings = useAppStore((s) => s.updateSettings);
  const setSettingsOpen = useAppStore((s) => s.setSettingsOpen);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const pickAndOpen = async () => {
    setError(null);
    const dir = await open({ directory: true, title: '选择 WebGAL 项目目录' });
    if (typeof dir !== 'string') return;
    await openPath(dir);
  };

  const openPath = async (path: string) => {
    setBusy(true);
    setError(null);
    try {
      await openProject(path);
    } catch (e) {
      setError(String(e));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="welcome">
      <div className="welcome-inner">
        <h1 className="welcome-title">WebGAL Ink</h1>
        <p className="welcome-subtitle">WebGAL 场景脚本编辑器</p>

        <div className="welcome-actions">
          <Button
            appearance="primary"
            size="large"
            icon={<FolderOpenRegular />}
            onClick={() => void pickAndOpen()}
            disabled={busy}
          >
            打开项目
          </Button>
          <Button
            size="large"
            icon={theme === 'dark' ? <WeatherSunnyRegular /> : <WeatherMoonRegular />}
            onClick={() => updateSettings({ theme: theme === 'dark' ? 'light' : 'dark' })}
            title="切换主题"
          >
            主题
          </Button>
          <Button size="large" icon={<SettingsRegular />} onClick={() => setSettingsOpen(true)}>
            设置
          </Button>
        </div>

        {busy ? <Spinner label="正在打开项目…" /> : null}
        {error ? <div className="welcome-error">{error}</div> : null}

        {settings.recentProjects.length > 0 ? (
          <div className="recent-projects">
            <h3>最近项目</h3>
            <ul>
              {settings.recentProjects.map((p) => (
                <li key={p}>
                  <button onClick={() => void openPath(p)}>{p}</button>
                </li>
              ))}
            </ul>
          </div>
        ) : null}
      </div>
    </div>
  );
}
